-- Full Habbo furni library: create furniture rows for every official
-- furni not already defined. Idempotent (anti-join on item_name);
-- never touches legacy/custom rows. Conservative interaction.
DROP TEMPORARY TABLE IF EXISTS _furni_stage;
CREATE TEMPORARY TABLE _furni_stage (item_name VARCHAR(70), public_name VARCHAR(56), type VARCHAR(4), width INT, length INT, stack_height DOUBLE, can_stack VARCHAR(1), can_sit VARCHAR(1), is_walkable VARCHAR(1), sprite_id INT, allow_recycle VARCHAR(1), allow_trade VARCHAR(1));
